45:   const mediaRecorderRef = useRef<MediaRecorder | null>(null);
46:   const chunksRef = useRef<Blob[]>([]);
47: 
48:   useEffect(() => {
49:     if (!seed) return;
50:     setDraft(seed);
51:     onSeedConsumed?.();
52:     areaRef.current?.focus();
53:   }, [seed, onSeedConsumed]);
54: 
55:   // Auto-expand the textarea up to a comfortable ceiling.
56:   useEffect(() => {
57:     const el = areaRef.current;
58:     if (!el) return;
59:     el.style.height = '0px';
60:     el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
61:   }, [draft]);
62: 
63:   // Microphone hardware must never outlive the component.
64:   useEffect(() => {
65:     return () => {
66:       if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
67:         try {
68:           mediaRecorderRef.current.stop();
69:         } catch {
70:           // cleanup
71:         }
72:       }
73:       streamRef.current?.getTracks().forEach((track) => track.stop());
74:       void ctxRef.current?.close();
75:     };
76:   }, []);
77: 
78:   const releaseCapture = () => {
79:     streamRef.current?.getTracks().forEach((track) => track.stop());
80:     streamRef.current = null;
81:     void ctxRef.current?.close();
82:     ctxRef.current = null;
83:     setAnalyser(null);
84:   };
85: 
86:   const transcribeAudio = async (audioBlob: Blob) => {
87:     try {
88:       setNotice('Transcribing audio...');
89:       const formData = new FormData();
90:       formData.append('file', audioBlob, 'recording.webm');
91: 
92:       const headers: Record<string, string> = {};
93:       const token = getBearerToken();
94:       if (token) {
95:         headers['Authorization'] = `Bearer ${token}`;
96:       }
97: 
98:       const res = await fetch('/api/v1/voice/transcribe', {
99:         method: 'POST',
100:         headers,
101:         body: formData,
102:       });
103: 
104:       if (!res.ok) {
105:         throw new Error(`Transcription failed (${res.status})`);
106:       }
107: 
108:       const data = (await res.json()) as { text?: string };
109:       const transcribedText = data?.text?.trim();
110:       if (transcribedText) {
111:         setDraft((prev) => (prev ? `${prev.trim()} ${transcribedText}` : transcribedText));
112:         setNotice(null);
113:         areaRef.current?.focus();
114:       } else {
115:         setNotice('No speech recognized.');
116:       }
117: 
118:     } catch {
119:       setNotice('Voice transcription failed. You can type your message instead.');
120:     }
121:   };
122: 
123:   const startCapture = async () => {
124:     if (!navigator.mediaDevices?.getUserMedia) {
125:       setNotice('This browser exposes no microphone to the page.');
126:       return;
127:     }
128:     try {
129:       const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
130:       streamRef.current = stream;
131: 
132:       const ctx = new AudioContext();
133:       ctxRef.current = ctx;
134:       const source = ctx.createMediaStreamSource(stream);
135:       const node = ctx.createAnalyser();
136:       node.fftSize = 1024;
137:       node.smoothingTimeConstant = 0.65;
138:       source.connect(node);
139: 
140:       setAnalyser(node);
141: 
142:       chunksRef.current = [];
143:       if (typeof MediaRecorder !== 'undefined') {
144:         const recorder = new MediaRecorder(stream);
145:         recorder.ondataavailable = (event) => {
146:           if (event.data && event.data.size > 0) {
147:             chunksRef.current.push(event.data);
148:           }
149:         };
150:         recorder.start(100);
151:         mediaRecorderRef.current = recorder;
152:       }
153: 
154:       setRecording(true);
155:       setNotice(null);
156:     } catch {
157:       setNotice('Microphone permission was declined, so nothing is being captured.');
158:     }
159:   };
160: 
161:   const stopCapture = () => {
162:     setRecording(false);
163:     const recorder = mediaRecorderRef.current;
164:     if (recorder && recorder.state !== 'inactive') {
165:       recorder.onstop = () => {
166:         const chunks = chunksRef.current;
167:         if (chunks.length > 0) {
168:           const audioBlob = new Blob(chunks, { type: 'audio/webm' });
169:           void transcribeAudio(audioBlob);
170:         }
171:       };
172:       try {
173:         recorder.stop();
174:       } catch {
175:         // Fallback
176:       }
177:     }
178:     mediaRecorderRef.current = null;
179:     releaseCapture();
180:   };
181: 
182: 
183:   const toggleRecording = () => {
184:     if (recording) {
185:       stopCapture();
186:       return;
187:     }
188:     setNotice(null);
189:     void startCapture();
190:   };
191: 
192:   const canSend = (draft.trim().length > 0 || files.length > 0) && !streaming && !disabled;
193: 
194:   const submit = () => {
195:     if (!canSend) return;
196:     onSend(draft);
197:     setDraft('');
198:     setFiles([]);
199:     setNotice(null);
200:   };
201: 
202:   const phase: BeamPhase = recording
203:     ? 'listening'
