236:                   </button>
237:                 </span>
238:               ))}
239:             </motion.div>
240:           )}
241:         </AnimatePresence>
242: 
243:         {notice ? (
244:           <p role="status" className="mb-2 px-3 text-[12px] text-[var(--text-muted)]">
245:             {notice}
