261:         >
262:           <div className="flex items-end gap-2 p-2">
263:             <input
264:               ref={fileRef}
265:               type="file"
266:               multiple
267:               hidden
268:               onChange={(e) => {
269:                 const names = Array.from(e.target.files ?? []).map((f) => f.name);
270:                 setFiles((fs) => [...fs, ...names]);
271:                 e.target.value = '';
272:               }}
273:             />
274:             <button
275:               type="button"
276:               aria-label="Attach a file"
277:               onClick={() => fileRef.current?.click()}
278:               disabled={disabled}
279:               className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--text)_8%,transparent)] text-[var(--text-muted)] transition-transform duration-300 ease-spring hover:scale-105 hover:text-[var(--text)] active:scale-95 disabled:opacity-40"
280:             >
281:               <Plus size={18} strokeWidth={1.5} />
282:             </button>
283: 
284:             <div className="flex min-h-11 flex-1 items-center">
285:               {recording ? (
286:                 <div className="flex items-center gap-3 px-2 text-sm text-[var(--text-muted)]">
287:                   <span className="relative flex h-2 w-2">
288:                     <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-[var(--text)] opacity-60" />
289:                     <span className="relative inline-flex h-2 w-2 rounded-full bg-[var(--text)]" />
290:                   </span>
291:                   Listening...
292:                 </div>
293:               ) : (
294:                 <label htmlFor="vigil-composer" className="sr-only">
295:                   Message Vigil
296:                 </label>
297:               )}
298:               {recording ? null : (
299:                 <textarea
300:                   id="vigil-composer"
301:                   ref={areaRef}
302:                   rows={1}
303:                   value={draft}
304:                   onChange={(e) => setDraft(e.target.value)}
305:                   onKeyDown={(e) => {
306:                     if (e.key === 'Enter' && !e.shiftKey) {
307:                       e.preventDefault();
