324:               className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-[var(--text-muted)] transition-transform duration-300 ease-spring hover:scale-105 hover:text-[var(--text)] active:scale-95 disabled:opacity-40"
325:               style={
