332:               }
333:             >
334:               <Mic size={18} strokeWidth={1.5} />
335:             </button>
336: 
337:             <button
338:               type="button"
339:               aria-label={streaming ? 'Stop generating' : 'Send'}
340:               disabled={!streaming && !canSend}
341:               onClick={streaming ? onStop : submit}
342:               className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full transition-all duration-300 ease-spring active:scale-95"
343:               style={
